Data.data:
body {
  background-image: url("https://s.guyue.me/img/bg.jpg");
  background-repeat: no-repeat;
  background-attachment: fixed;
  background-size: cover;
  opacity: 0.8;
}
img {
  loading: lazy;
}
.fa {
  font-display: swap;
}
.post-block,
.post-block + .post-block {
  border-radius: 8px;
  margin-top: 24px;
}
.posts-collapse .post-block {
  border-radius: 8px;
}
.post-block {
  margin-bottom: 24px;
  background: #fff;
  padding: 20px;
}
.sidebar {
  margin-top: 0px;
}
.sidebar-inner {
  border-radius: 8px;
}
.btn {
  border-radius: 8px;
}
.highlight {
  border-radius: 8px;
}
.search-input {
  border-radius: 8px;
}
.tag-cloud-tags a {
  border-radius: 8px;
}
.header-inner {
  border-radius: 8px;
  background: linear-gradient(to bottom, #222 30%, #fff 30%);
}
.main-inner {
  border-radius: 8px;
}
.menu {
  border-radius: 0;
  background: transparent;
  margin-top: 0;
}
.menu-item {
  border-radius: 0;
}
.menu-item-active {
  border-radius: 0;
}
.menu-item a {
  background: transparent;
  color: #000;
}
.menu-item-active a {
  background: transparent;
}
.pagination {
  border-radius: 8px;
  margin-top: 24px;
}
